import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { texture, uv, vec2, vec3, sin, fract, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const accent = new THREE.Color(colors.accent ?? '#ff2a38');

  const group = new THREE.Group();
  group.name = 'hub-features-card-2';

  const atlas = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = (atlas.w || 512) / (atlas.h || 320);
  const planeH = 1.0;
  const planeW = planeH * aspect;

  const inner = new THREE.Group();
  group.add(inner);

  // --- sprite plane (textured, atlas-cropped) ---
  const geo = new THREE.PlaneGeometry(planeW, planeH, 1, 1);

  const placeholder = new THREE.Texture();
  placeholder.flipY = false;
  placeholder.minFilter = THREE.LinearFilter;
  placeholder.magFilter = THREE.LinearFilter;

  const mapNode = texture(placeholder);
  // subtle engineered grain
  const n = fract(sin(dot(uv().mul(900.0), vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = n.sub(0.5).mul(2.0).mul(0.03);

  const mat = new MeshBasicNodeMaterial();
  mat.colorNode = mapNode.add(vec3(grain));
  mat.transparent = true;
  mat.opacity = 0.0;
  mat.side = THREE.DoubleSide;
  mat.toneMapped = true;

  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = 3;
  inner.add(mesh);

  // --- accent haze behind sprite (engineered gradient veil) ---
  const hazeGeo = new THREE.PlaneGeometry(planeW * 1.35, planeH * 1.5);
  const hazeMat = new MeshBasicNodeMaterial();
  hazeMat.colorNode = vec3(accent.r, accent.g, accent.b).mul(0.16);
  hazeMat.transparent = true;
  hazeMat.opacity = 0.0;
  hazeMat.depthWrite = false;
  hazeMat.toneMapped = true;
  const haze = new THREE.Mesh(hazeGeo, hazeMat);
  haze.position.z = -0.08;
  haze.renderOrder = 2;
  inner.add(haze);

  // --- load atlas texture and apply region UVs ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      const img = tex.image;
      const aw = (img && (img.width || img.naturalWidth)) || atlas.w;
      const ah = (img && (img.height || img.naturalHeight)) || atlas.h;

      placeholder.copy(tex);
      placeholder.flipY = false;
      placeholder.wrapS = THREE.ClampToEdgeWrapping;
      placeholder.wrapT = THREE.ClampToEdgeWrapping;
      placeholder.minFilter = THREE.LinearMipmapLinearFilter;
      placeholder.magFilter = THREE.LinearFilter;
      placeholder.generateMipmaps = true;

      placeholder.repeat.set((atlas.w || 512) / aw, (atlas.h || 320) / ah);
      // flipY=false -> origin at top-left of the image
      placeholder.offset.set((atlas.x || 0) / aw, 1.0 - ((atlas.y || 0) + (atlas.h || 320)) / ah);
      placeholder.needsUpdate = true;
      mat.needsUpdate = true;
    });
  }

  // --- weighted-settle entrance (one-time, then static) ---
  const tl = gsap.timeline();
  inner.position.y = 0.2;
  tl.to(mat, { opacity: 1.0, duration: 0.55, ease: 'power2.out' }, 0);
  tl.to(hazeMat, { opacity: 0.55, duration: 0.7, ease: 'power2.out' }, 0.05);
  tl.fromTo(inner.position, { y: 0.2 }, { y: 0, duration: 0.85, ease: 'power3.out' }, 0);
  tl.fromTo(inner.scale, { x: 1.04, y: 1.04 }, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 0.05);

  // --- handlers (none interactive, but contract-ready) ---
  group.userData.handlers = {};

  // --- cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
    hazeGeo.dispose();
    hazeMat.dispose();
    placeholder.dispose && placeholder.dispose();
  };

  return group;
}
